css:
body {
    font-family: Arial, sans-serif;
    font-size: 12px;
    margin: 0;
    padding: 0;
}

.container {
    width: 100%;
    max-width: 800px;
    margin: 0 auto;
    padding: 20px;
    border: 1px solid #000;
}

.header {
    text-align: left;
    margin-bottom: 20px;
}

.header img {
    width: 100px;
    vertical-align: top;
}

.header .title {
    text-align: right;
    font-size: 18px;
    text-transform: uppercase;
    font-weight: bold;
}

.header-table,
.details-table,
.particulars-table,
.additional-details-table {
    width: 100%;
    border-collapse: collapse;
    margin-bottom: 20px;
}

.header-table td,
.details-table td {
    border: 1px solid #000;
    padding: 5px;
    vertical-align: top;
}

.header-table td {
    width: 50%;
}

.header-table .scac {
    text-align: right;
    font-size: 14px;
    font-weight: bold;
}

.header-table .bl-number {
    text-align: right;
    font-size: 14px;
    font-weight: bold;
}

.details-table th,
.details-table td,
.additional-details-table th,
.additional-details-table td {
    text-align: left;
    padding: 5px;
    border: 1px solid #000;
    font-weight: normal;
}

.particulars-table th,
.particulars-table td {
    border: 1px solid #000;
    padding: 5px;
    text-align: left;
    vertical-align: top;
}

.particulars-table .section-title {
    font-weight: bold;
    border-bottom: 2px solid #000;
    text-align: center;
}

.certified {
    text-align: center;
    font-size: 50px;
    color: #ccc;
    font-weight: bold;
    margin-top: 50px;
}

.footer {
    margin-top: 30px;
    border-top: 1px solid #000;
    padding-top: 10px;
}

.footer-section {
    margin-bottom: 10px;
}

.note, .terms {
    text-align: center;
    margin-top: 10px;
    font-weight: bold;
}
.section-title {
    font-weight: bold;
    text-align: center;
}
